INSERT INTO "blobs" ("sha256", "data", "size")
  SELECT DISTINCT ON (h) h, "tarball", length("tarball")
    FROM (SELECT encode(sha256("tarball"), 'hex') AS h, "tarball" FROM "versions" WHERE "tarball" IS NOT NULL) t
  ON CONFLICT ("sha256") DO NOTHING;--> statement-breakpoint
UPDATE "versions" SET "blob_sha256" = encode(sha256("tarball"), 'hex') WHERE "tarball" IS NOT NULL;--> statement-breakpoint
DO $$
DECLARE with_tarball bigint; with_blob bigint; distinct_hashes bigint; blob_rows bigint; mismatched bigint;
BEGIN
  SELECT count(*) FILTER (WHERE "tarball" IS NOT NULL), count(*) FILTER (WHERE "blob_sha256" IS NOT NULL),
         count(DISTINCT encode(sha256("tarball"), 'hex'))
    INTO with_tarball, with_blob, distinct_hashes FROM "versions";
  SELECT count(*) INTO blob_rows FROM "blobs";
  SELECT count(*) INTO mismatched FROM "versions" v LEFT JOIN "blobs" b ON b."sha256" = v."blob_sha256"
   WHERE v."tarball" IS NOT NULL AND b."data" IS DISTINCT FROM v."tarball";
  IF with_tarball <> with_blob OR distinct_hashes <> blob_rows OR mismatched <> 0 THEN
    RAISE EXCEPTION 'tarball move check failed: % tarballs, % with blob, % distinct hashes, % blobs, % mismatched',
      with_tarball, with_blob, distinct_hashes, blob_rows, mismatched;
  END IF;
END $$;--> statement-breakpoint
